// Get raw phone number from webhook
const rawPhone = $('Webhook').first().json.body.phone_number;

// Normalize to E.164 (+##########)
function normalizePhone(phone) {
  if (!phone) return null;

  // Keep digits only
  const digits = phone.replace(/\D/g, '');

  // If US number with country code
  if (digits.length === 11 && digits.startsWith('1')) {
    return `+${digits}`;
  }

  // If US number without country code
  if (digits.length === 10) {
    return `+1${digits}`;
  }

  // Fallback: return with +
  return `+${digits}`;
}

const normalizedPhone = normalizePhone(rawPhone);

return [
  {
    json: {
      phone_normalized: normalizedPhone
    }
  }
];
